contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public {
        address oldOwner = c.owner();
        bool reverted;
        if (oldOwner == address(this)) {
            try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
            assert(!reverted && c.owner() == newOwner);
        } else {
            try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
            assert(reverted && c.owner() == oldOwner);
        }
    }
}

